[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>CreativeHub — Online Classes for Creatives</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Plus+Jakarta+Sans:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    :root {
      --black: #000000;
      --accent-green: #55DA9B;
      --accent-purple: #5620C1;
      --white: #ffffff;
      --gray-100: #f5f5f5;
      --gray-200: #e5e5e5;
      --gray-300: #d4d4d4;
      --gray-400: #a3a3a3;
      --gray-500: #737373;
      --gray-600: #525252;
      --gray-700: #404040;
      --gray-800: #262626;
      --gray-900: #1a1a1a;
      --navy: #0f172a;
      --coral: #ff6b5b;
      --warm-yellow: #ffc83d;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: 'Plus Jakarta Sans', -apple-system, BlinkMacSystemFont, sans-serif;
      background: var(--white);
      color: var(--black);
      line-height: 1.6;
      -webkit-font-smoothing: antialiased;
    }

    img {
      max-width: 100%;
      display: block;
    }

    a {
      text-decoration: none;
      color: inherit;
    }

    /* ============ HEADER ============ */
    header {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(255, 255, 255, 0.95);
      backdrop-filter: blur(10px);
      border-bottom: 1px solid var(--gray-200);
      padding: 0 24px;
    }

    .header-inner {
      max-width: 1280px;
      margin: 0 auto;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .logo {
      font-size: 24px;
      font-weight: 800;
      color: var(--black);
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .logo-icon {
      width: 36px;
      height: 36px;
      background: linear-gradient(135deg, var(--accent-green), var(--accent-purple));
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .logo-icon svg {
      width: 20px;
      height: 20px;
      fill: var(--white);
    }

    nav {
      display: flex;
      align-items: center;
      gap: 32px;
    }

    nav a {
      font-size: 15px;
      font-weight: 500;
      color: var(--gray-600);
      transition: color 0.2s;
    }

    nav a:hover {
      color: var(--black);
    }

    .header-actions {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .btn-ghost {
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 600;
      border-radius: 10px;
      background: transparent;
      border: none;
      cursor: pointer;
      transition: background 0.2s;
    }

    .btn-ghost:hover {
      background: var(--gray-100);
    }

    .btn-primary {
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 600;
      border-radius: 10px;
      background: var(--black);
      color: var(--white);
      border: none;
      cursor: pointer;
      transition: background 0.2s, transform 0.2s;
    }

    .btn-primary:hover {
      background: var(--gray-800);
      transform: translateY(-1px);
    }

    .mobile-menu-btn {
      display: none;
      background: none;
      border: none;
      cursor: pointer;
      padding: 8px;
    }

    /* ============ HERO ============ */
    .hero {
      background: var(--navy);
      padding: 140px 24px 80px;
      text-align: center;
      position: relative;
      overflow: hidden;
    }

    .hero::before {
      content: '';
      position: absolute;
      top: -50%;
      right: -20%;
      width: 600px;
      height: 600px;
      background: radial-gradient(circle, rgba(85, 218, 155, 0.15) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero::after {
      content: '';
      position: absolute;
      bottom: -30%;
      left: -10%;
      width: 500px;
      height: 500px;
      background: radial-gradient(circle, rgba(86, 32, 193, 0.2) 0%, transparent 70%);
      pointer-events: none;
    }

    .hero-inner {
      max-width: 900px;
      margin: 0 auto;
      position: relative;
      z-index: 1;
    }

    .hero-badge {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      background: rgba(85, 218, 155, 0.15);
      border: 1px solid rgba(85, 218, 155, 0.3);
      padding: 8px 16px;
      border-radius: 100px;
      margin-bottom: 24px;
    }

    .hero-badge span {
      color: var(--accent-green);
      font-size: 14px;
      font-weight: 600;
    }

    .hero h1 {
      font-size: clamp(40px, 7vw, 64px);
      font-weight: 800;
      color: var(--white);
      line-height: 1.1;
      margin-bottom: 20px;
    }

    .hero h1 .highlight {
      background: linear-gradient(135deg, var(--accent-green), var(--warm-yellow));
      -webkit-background-clip: text;
      -webkit-text-fill-color: transparent;
      background-clip: text;
    }

    .hero-subtitle {
      font-size: 20px;
      color: var(--gray-400);
      margin-bottom: 40px;
    }

    .hero-ctas {
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 12px;
      margin-bottom: 48px;
    }

    .btn-google {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 12px;
      width: 100%;
      max-width: 380px;
      padding: 16px 24px;
      font-size: 16px;
      font-weight: 600;
      color: var(--gray-900);
      background: var(--white);
      border: none;
      border-radius: 14px;
      cursor: pointer;
      transition: transform 0.2s, box-shadow 0.2s;
    }

    .btn-google:hover {
      transform: translateY(-2px);
      box-shadow: 0 8px 30px rgba(0, 0, 0, 0.3);
    }

    .btn-google svg {
      width: 22px;
      height: 22px;
    }

    .btn-email {
      display: flex;
      align-items: center;
      justify-content: center;
      width: 100%;
      max-width: 380px;
      padding: 16px 24px;
      font-size: 16px;
      font-weight: 600;
      color: var(--white);
      background: var(--accent-green);
      border: none;
      border-radius: 14px;
      cursor: pointer;
      transition: transform 0.2s, background 0.2s;
    }

    .btn-email:hover {
      transform: translateY(-2px);
      background: #4bc98d;
    }

    .hero-legal {
      font-size: 11px;
      color: var(--gray-500);
      max-width: 380px;
      margin: 0 auto;
      line-height: 1.5;
    }

    .category-pills {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 10px;
      margin-top: 48px;
    }

    .category-pill {
      padding: 8px 16px;
      font-size: 13px;
      font-weight: 500;
      color: var(--gray-300);
      background: rgba(255, 255, 255, 0.08);
      border: 1px solid rgba(255, 255, 255, 0.1);
      border-radius: 100px;
      cursor: pointer;
      transition: all 0.2s;
    }

    .category-pill:hover {
      background: rgba(255, 255, 255, 0.15);
      color: var(--white);
      border-color: rgba(255, 255, 255, 0.2);
    }

    /* ============ FEATURES ============ */
    .features {
      padding: 100px 24px;
      background: var(--white);
    }

    .features-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .features-header {
      text-align: center;
      margin-bottom: 64px;
    }

    .section-label {
      display: inline-block;
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1.5px;
      color: var(--accent-green);
      margin-bottom: 16px;
    }

    .section-title {
      font-size: clamp(32px, 5vw, 44px);
      font-weight: 800;
      color: var(--black);
      line-height: 1.2;
    }

    .features-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
      gap: 24px;
    }

    .feature-card {
      background: var(--gray-100);
      border-radius: 20px;
      padding: 32px;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .feature-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 20px 40px rgba(0, 0, 0, 0.08);
    }

    .feature-icon {
      width: 56px;
      height: 56px;
      background: linear-gradient(135deg, var(--accent-green), var(--accent-purple));
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 20px;
    }

    .feature-icon svg {
      width: 28px;
      height: 28px;
      fill: var(--white);
    }

    .feature-card h3 {
      font-size: 20px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 8px;
    }

    .feature-card p {
      font-size: 15px;
      color: var(--gray-500);
      line-height: 1.6;
    }

    /* ============ STATS ============ */
    .stats {
      background: var(--black);
      padding: 80px 24px;
    }

    .stats-inner {
      max-width: 1200px;
      margin: 0 auto;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 48px;
    }

    .stat-item {
      text-align: center;
    }

    .stat-number {
      font-size: clamp(48px, 8vw, 72px);
      font-weight: 800;
      color: var(--white);
      line-height: 1;
      margin-bottom: 8px;
    }

    .stat-number .accent {
      color: var(--accent-green);
    }

    .stat-label {
      font-size: 16px;
      color: var(--gray-400);
      font-weight: 500;
    }

    .stat-stars {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 4px;
      margin-top: 8px;
    }

    .stat-stars svg {
      width: 20px;
      height: 20px;
      fill: var(--warm-yellow);
    }

    /* ============ COURSES ============ */
    .courses {
      padding: 100px 24px;
      background: var(--gray-100);
    }

    .courses-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .courses-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .category-tabs {
      display: flex;
      flex-wrap: wrap;
      justify-content: center;
      gap: 8px;
      margin-bottom: 48px;
    }

    .category-tab {
      padding: 10px 20px;
      font-size: 14px;
      font-weight: 600;
      color: var(--gray-600);
      background: var(--white);
      border: 1px solid var(--gray-200);
      border-radius: 100px;
      cursor: pointer;
      transition: all 0.2s;
    }

    .category-tab:hover {
      border-color: var(--gray-400);
      color: var(--black);
    }

    .category-tab.active {
      background: var(--black);
      color: var(--white);
      border-color: var(--black);
    }

    .courses-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
      gap: 24px;
    }

    .course-card {
      background: var(--white);
      border-radius: 20px;
      overflow: hidden;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .course-card:hover {
      transform: translateY(-6px);
      box-shadow: 0 20px 50px rgba(0, 0, 0, 0.1);
    }

    .course-thumb {
      height: 160px;
      background: linear-gradient(135deg, var(--gray-200), var(--gray-300));
      position: relative;
      overflow: hidden;
    }

    .course-thumb-pattern {
      position: absolute;
      inset: 0;
      opacity: 0.5;
    }

    .course-thumb-icon {
      position: absolute;
      top: 50%;
      left: 50%;
      transform: translate(-50%, -50%);
      width: 48px;
      height: 48px;
      background: rgba(0, 0, 0, 0.4);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .course-thumb-icon svg {
      width: 20px;
      height: 20px;
      fill: var(--white);
    }

    .course-info {
      padding: 20px;
    }

    .course-category {
      font-size: 12px;
      font-weight: 600;
      color: var(--accent-purple);
      text-transform: uppercase;
      letter-spacing: 0.5px;
      margin-bottom: 8px;
    }

    .course-title {
      font-size: 16px;
      font-weight: 700;
      color: var(--black);
      line-height: 1.4;
      margin-bottom: 12px;
      display: -webkit-box;
      -webkit-line-clamp: 2;
      -webkit-box-orient: vertical;
      overflow: hidden;
    }

    .course-meta {
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 13px;
      color: var(--gray-500);
    }

    .course-meta span {
      display: flex;
      align-items: center;
      gap: 4px;
    }

    .course-meta svg {
      width: 14px;
      height: 14px;
      fill: var(--gray-400);
    }

    /* ============ CREATIVE FEED ============ */
    .creative-feed {
      padding: 100px 24px;
      background: var(--white);
    }

    .creative-feed-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .feed-header {
      text-align: center;
      margin-bottom: 64px;
    }

    .feed-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(300px, 1fr));
      gap: 32px;
    }

    .feed-card {
      background: var(--gray-100);
      border-radius: 24px;
      padding: 40px 32px;
      position: relative;
      overflow: hidden;
      transition: transform 0.3s;
    }

    .feed-card:hover {
      transform: translateY(-4px);
    }

    .feed-card::before {
      content: '';
      position: absolute;
      top: 0;
      right: 0;
      width: 200px;
      height: 200px;
      border-radius: 50%;
      opacity: 0.1;
    }

    .feed-card:nth-child(1)::before {
      background: var(--accent-green);
    }

    .feed-card:nth-child(2)::before {
      background: var(--accent-purple);
    }

    .feed-card:nth-child(3)::before {
      background: var(--coral);
    }

    .feed-icon {
      width: 64px;
      height: 64px;
      border-radius: 20px;
      display: flex;
      align-items: center;
      justify-content: center;
      margin-bottom: 24px;
    }

    .feed-card:nth-child(1) .feed-icon {
      background: rgba(85, 218, 155, 0.15);
    }

    .feed-card:nth-child(2) .feed-icon {
      background: rgba(86, 32, 193, 0.15);
    }

    .feed-card:nth-child(3) .feed-icon {
      background: rgba(255, 107, 91, 0.15);
    }

    .feed-icon svg {
      width: 32px;
      height: 32px;
    }

    .feed-card:nth-child(1) .feed-icon svg {
      fill: var(--accent-green);
    }

    .feed-card:nth-child(2) .feed-icon svg {
      fill: var(--accent-purple);
    }

    .feed-card:nth-child(3) .feed-icon svg {
      fill: var(--coral);
    }

    .feed-card h3 {
      font-size: 24px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 12px;
    }

    .feed-card p {
      font-size: 15px;
      color: var(--gray-600);
      line-height: 1.7;
    }

    /* ============ TEACHERS ============ */
    .teachers {
      padding: 100px 24px;
      background: var(--gray-100);
      overflow: hidden;
    }

    .teachers-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .teachers-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .teachers-subtitle {
      font-size: 18px;
      color: var(--gray-600);
      max-width: 600px;
      margin: 16px auto 0;
    }

    .teachers-carousel {
      position: relative;
    }

    .teachers-track {
      display: flex;
      gap: 24px;
      overflow-x: auto;
      scroll-behavior: smooth;
      scrollbar-width: none;
      -ms-overflow-style: none;
      padding: 16px 0;
    }

    .teachers-track::-webkit-scrollbar {
      display: none;
    }

    .teacher-card {
      flex: 0 0 280px;
      background: var(--white);
      border-radius: 24px;
      padding: 32px;
      text-align: center;
      transition: transform 0.3s, box-shadow 0.3s;
    }

    .teacher-card:hover {
      transform: translateY(-4px);
      box-shadow: 0 20px 50px rgba(0, 0, 0, 0.08);
    }

    .teacher-avatar {
      width: 100px;
      height: 100px;
      border-radius: 50%;
      margin: 0 auto 20px;
      background: linear-gradient(135deg, var(--gray-200), var(--gray-300));
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 40px;
      font-weight: 700;
      color: var(--gray-500);
    }

    .teacher-card:nth-child(1) .teacher-avatar { background: linear-gradient(135deg, #ffe4d6, #ffd0c4); color: #c45a3b; }
    .teacher-card:nth-child(2) .teacher-avatar { background: linear-gradient(135deg, #d4f0ff, #b8e4ff); color: #2a7aa8; }
    .teacher-card:nth-child(3) .teacher-avatar { background: linear-gradient(135deg, #e4d4ff, #d0c4ff); color: #6b3db8; }
    .teacher-card:nth-child(4) .teacher-avatar { background: linear-gradient(135deg, #d4ffe4, #b8ffc8); color: #2da85c; }
    .teacher-card:nth-child(5) .teacher-avatar { background: linear-gradient(135deg, #fffbd4, #fff5b8); color: #b89a2a; }
    .teacher-card:nth-child(6) .teacher-avatar { background: linear-gradient(135deg, #ffd4f0, #ffb8e4); color: #a82a8a; }
    .teacher-card:nth-child(7) .teacher-avatar { background: linear-gradient(135deg, #d4fff0, #b8ffe4); color: #2aa87a; }
    .teacher-card:nth-child(8) .teacher-avatar { background: linear-gradient(135deg, #ffd4d4, #ffb8b8); color: #a82a2a; }

    .teacher-name {
      font-size: 18px;
      font-weight: 700;
      color: var(--black);
      margin-bottom: 4px;
    }

    .teacher-specialty {
      font-size: 14px;
      color: var(--gray-500);
    }

    .carousel-nav {
      display: flex;
      justify-content: center;
      gap: 12px;
      margin-top: 32px;
    }

    .carousel-btn {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: var(--white);
      border: 1px solid var(--gray-200);
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: center;
      transition: all 0.2s;
    }

    .carousel-btn:hover {
      background: var(--black);
      border-color: var(--black);
    }

    .carousel-btn:hover svg {
      fill: var(--white);
    }

    .carousel-btn svg {
      width: 20px;
      height: 20px;
      fill: var(--black);
      transition: fill 0.2s;
    }

    /* ============ TESTIMONIALS ============ */
    .testimonials {
      padding: 100px 24px;
      background: var(--white);
    }

    .testimonials-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .testimonials-header {
      text-align: center;
      margin-bottom: 64px;
    }

    .testimonials-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 24px;
    }

    .testimonial-card {
      background: var(--gray-100);
      border-radius: 24px;
      padding: 32px;
      position: relative;
    }

    .testimonial-quote {
      font-size: 16px;
      color: var(--gray-700);
      line-height: 1.7;
      margin-bottom: 24px;
      font-style: italic;
    }

    .testimonial-author {
      display: flex;
      align-items: center;
      gap: 12px;
    }

    .testimonial-avatar {
      width: 48px;
      height: 48px;
      border-radius: 50%;
      background: linear-gradient(135deg, var(--accent-green), var(--accent-purple));
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 20px;
      font-weight: 700;
      color: var(--white);
    }

    .testimonial-name {
      font-size: 15px;
      font-weight: 700;
      color: var(--black);
    }

    .testimonial-stars {
      display: flex;
      gap: 2px;
      margin-top: 4px;
    }

    .testimonial-stars svg {
      width: 14px;
      height: 14px;
      fill: var(--warm-yellow);
    }

    /* ============ TEAMS ============ */
    .teams {
      padding: 100px 24px;
      background: var(--navy);
      text-align: center;
    }

    .teams-inner {
      max-width: 800px;
      margin: 0 auto;
    }

    .teams h2 {
      font-size: clamp(32px, 5vw, 44px);
      font-weight: 800;
      color: var(--white);
      margin-bottom: 20px;
    }

    .teams p {
      font-size: 18px;
      color: var(--gray-400);
      line-height: 1.7;
      margin-bottom: 40px;
    }

    .btn-teams {
      display: inline-flex;
      align-items: center;
      gap: 8px;
      padding: 16px 32px;
      font-size: 16px;
      font-weight: 600;
      color: var(--black);
      background: var(--accent-green);
      border-radius: 14px;
      border: none;
      cursor: pointer;
      transition: transform 0.2s, background 0.2s;
    }

    .btn-teams:hover {
      transform: translateY(-2px);
      background: #4bc98d;
    }

    /* ============ FAQ ============ */
    .faq {
      padding: 100px 24px;
      background: var(--gray-100);
    }

    .faq-inner {
      max-width: 800px;
      margin: 0 auto;
    }

    .faq-header {
      text-align: center;
      margin-bottom: 48px;
    }

    .faq-list {
      display: flex;
      flex-direction: column;
      gap: 12px;
    }

    .faq-item {
      background: var(--white);
      border-radius: 16px;
      overflow: hidden;
    }

    .faq-question {
      width: 100%;
      padding: 24px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      font-size: 16px;
      font-weight: 600;
      color: var(--black);
      background: none;
      border: none;
      cursor: pointer;
      text-align: left;
      gap: 16px;
    }

    .faq-question svg {
      width: 24px;
      height: 24px;
      fill: var(--gray-400);
      flex-shrink: 0;
      transition: transform 0.3s;
    }

    .faq-item.active .faq-question svg {
      transform: rotate(180deg);
    }

    .faq-answer {
      max-height: 0;
      overflow: hidden;
      transition: max-height 0.3s ease;
    }

    .faq-answer-inner {
      padding: 0 24px 24px;
      font-size: 15px;
      color: var(--gray-600);
      line-height: 1.7;
    }

    .faq-item.active .faq-answer {
      max-height: 300px;
    }

    /* ============ FOOTER ============ */
    footer {
      background: var(--black);
      padding: 80px 24px 40px;
    }

    .footer-inner {
      max-width: 1200px;
      margin: 0 auto;
    }

    .footer-top {
      display: grid;
      grid-template-columns: 2fr repeat(5, 1fr);
      gap: 48px;
      margin-bottom: 64px;
    }

    .footer-brand {
      color: var(--white);
    }

    .footer-brand .logo {
      color: var(--white);
      margin-bottom: 16px;
    }

    .footer-brand p {
      font-size: 14px;
      color: var(--gray-500);
      line-height: 1.7;
    }

    .footer-column h4 {
      font-size: 13px;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: 1px;
      color: var(--white);
      margin-bottom: 20px;
    }

    .footer-column ul {
      list-style: none;
    }

    .footer-column li {
      margin-bottom: 12px;
    }

    .footer-column a {
      font-size: 14px;
      color: var(--gray-500);
      transition: color 0.2s;
    }

    .footer-column a:hover {
      color: var(--white);
    }

    .footer-bottom {
      padding-top: 32px;
      border-top: 1px solid var(--gray-800);
      text-align: center;
    }

    .footer-bottom p {
      font-size: 13px;
      color: var(--gray-600);
    }

    /* ============ RESPONSIVE ============ */
    @media (max-width: 1024px) {
      .stats-inner {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-top {
        grid-template-columns: repeat(3, 1fr);
      }
    }

    @media (max-width: 768px) {
      nav {
        display: none;
      }

      .mobile-menu-btn {
        display: block;
      }

      .header-actions .btn-ghost {
        display: none;
      }

      .hero {
        padding: 120px 24px 60px;
      }

      .hero-ctas {
        gap: 10px;
      }

      .btn-google, .btn-email {
        max-width: 100%;
      }

      .category-pills {
        justify-content: flex-start;
        overflow-x: auto;
        flex-wrap: nowrap;
        padding-bottom: 8px;
        -webkit-overflow-scrolling: touch;
      }

      .category-pill {
        flex-shrink: 0;
      }

      .features-grid {
        grid-template-columns: 1fr;
      }

      .stats-inner {
        grid-template-columns: repeat(2, 1fr);
        gap: 32px;
      }

      .stat-number {
        font-size: 40px;
      }

      .courses-grid {
        grid-template-columns: 1fr;
      }

      .feed-grid {
        grid-template-columns: 1fr;
      }

      .teacher-card {
        flex: 0 0 260px;
      }

      .testimonials-grid {
        grid-template-columns: 1fr;
      }

      .footer-top {
        grid-template-columns: repeat(2, 1fr);
      }

      .footer-brand {
        grid-column: span 2;
      }
    }

    @media (max-width: 480px) {
      .stats-inner {
        grid-template-columns: 1fr 1fr;
      }

      .footer-top {
        grid-template-columns: 1fr;
      }

      .footer-brand {
        grid-column: span 1;
      }
    }
  </style>
